/* the nearest of the 8 directions of (dx, dy) as an angle (y grows to the south) */
int Combat_angle8( int dx, int dy ) {
	if ( dx < 0 && dy < 0 )	return 0x180;
	if ( dx > 0 && dy < 0 )	return 0x80;
	if ( dx < 0 && dy > 0 )	return 0x280;
	if ( dx > 0 && dy > 0 )	return 0x380;
	if ( dx < 0 )			return 0x200;
	if ( dx > 0 )			return 0;
	return dy < 0 ? 0x100 : 0x300;
}

